struct Vault {
    private let store: Store          // value type: no stored reference can leak to callers
    private let policy: Policy
    func read(subject: Subject, id: ID) throws -> Record {
        guard policy.allows(subject, id) else { throw AccessError.denied(id) }
        return try store.get(id)      // the only exported path to Store
    }
}
